$$
P(J(\mathbf{Y}) \leq t) = \int_{\{J(Y) \leq t\}} p(Y) dY, \tag{14a}
$$

$$
= \int_0^t \int_{\{J(Y) = x\}} p(Y) dY dx, \tag{14b}
$$

$$
\propto \int_0^t exp(-\frac{x}{\lambda}) \int_{\{J(Y) = x\}} dY dx, \tag{14c}
$$

$$
= \int_0^t exp(-\frac{x}{\lambda}) \frac{d V_J(x)}{dx} dx, \tag{14d}
$$

$$
\frac{\int_{0}^{\epsilon} exp(-\frac{t}{\lambda})dV_J(t)}{\int_{\epsilon}^{\infty} exp(-\frac{t}{\lambda})dV_J(t)} = \frac{exp(-\frac{\epsilon}{\lambda})V(\epsilon) + \frac{1}{\lambda}\int_{0}^{\epsilon} exp(-\frac{t}{\lambda})V_J(t)dt}{-exp(-\frac{\epsilon}{\lambda})V(\epsilon) + \frac{1}{\lambda}\int_{\epsilon}^{\infty} exp(-\frac{t}{\lambda})V_J(t)dt} \tag{20a}
$$

$$
\geq \frac{\int_{0}^{\epsilon} exp(-\frac{t}{\lambda})V_J(t)dt}{\int_{\epsilon}^{\infty} exp(-\frac{t}{\lambda})V_J(t)dt} \tag{20b}
$$

$$
\geq \frac{\int_{0}^{\epsilon} exp(-\frac{t}{\lambda})\sum_{k=0}^M c^l_k t^{\alpha_k} dt}{\int_{\epsilon}^{\infty} exp(-\frac{t}{\lambda})\sum_{k=0}^M c^u_k t^{\alpha_k} dt} \tag{20c}
$$
